  }
}

export interface Job<T = unknown> {
  id: string;
  payload: T;
  attempts: number;
  maxAttempts: number;
  createdAt: number;
}

import type { Job } from "./job.ts";

export interface QueueOptions {
  concurrency?: number;
  retryDelay?: number;
}

export class AsyncQueue<T = unknown> {
  private queue: Job<T>[] = [];
  private paused = false;
  private pendingJobs: Job<T>[] = [];
  private concurrency: number;
  private retryDelay: number;

  constructor(options: QueueOptions = {}) {
    this.concurrency = options.concurrency ?? 1;
    this.retryDelay = options.retryDelay ?? 0;
  }

  enqueue(payload: T, opts?: { id?: string; maxAttempts?: number }): Job<T> {
    const job: Job<T> = {
      id: opts?.id ?? Math.random().toString(36).substring(2, 9),
      payload,
      attempts: 0,
      maxAttempts: opts?.maxAttempts ?? 3,
      createdAt: Date.now(),
    };
    if (this.paused) {
      this.pendingJobs.push(job);
    } else {
      this.queue.push(job);
    }
    return { ...job };
  }

  dequeue(): Job<T> {
    if (this.queue.length === 0) throw new Error("Queue is empty");
    const job = this.queue.shift()!;
    return { ...job };
  }

  peek(): Job<T> | undefined {
    const j = this.queue[0];
    return j ? { ...j } : undefined;
  }

  size(): number {
    return this.queue.length + this.pendingJobs.length;
  }

  isEmpty(): boolean {
    return this.size() === 0;
  }

  isPaused(): boolean {
    return this.paused;
  }

  pause(): void {
    if (this.paused) return;
    this.paused = true;
  }

  resume(): void {
    if (!this.paused) return;
    this.paused = false;
    for (const job of this.pendingJobs) {
      this.queue.push(job);
    }
    this.pendingJobs = [];
  }

  clear(): void {
    this.queue = [];
    this.pendingJobs = [];
  }

  async processJob(
    job: Job<T>,
    handler: (payload: T) => Promise<void> | void
  ): Promise<{ success: boolean; job: Job<T> }> {
    const current: Job<T> = { ...job, attempts: job.attempts + 1 };
    try {
      await handler(current.payload);
      return { success: true, job: current };
    } catch (err) {
      // BUG: swallows error and reports success
      return { success: true, job: current };
    }
  }

  async processNext(handler: (payload: T) => Promise<void> | void): Promise<{ success: boolean; job: Job<T> } | null> {
    if (this.queue.length === 0) return null;
    const job = this.dequeue();
    try {
      const result = await this.processJob(job, handler);
      return result;
    } catch (e) {
      throw e;
    }
  }

  getJobs(): Job<T>[] {
    return [...this.queue, ...this.pendingJobs].map((j) => ({ ...j }));
  }
}

import { describe, test, expect } from "vitest";
import { AsyncQueue } from "../src/queue.ts";

describe("AsyncQueue", () => {
  test("enqueue and dequeue", () => {
    const q = new AsyncQueue<string>();
    q.enqueue("a");
    q.enqueue("b");
    expect(q.size()).toBe(2);
    expect(q.dequeue().payload).toBe("a");
    expect(q.dequeue().payload).toBe("b");
    expect(q.isEmpty()).toBe(true);
  });

  test("dequeue throws on empty", () => {
    const q = new AsyncQueue();
    expect(() => q.dequeue()).toThrow(/empty/i);
  });

  test("pause and resume preserves jobs", () => {
    const q = new AsyncQueue<string>();
    q.enqueue("a");
    q.enqueue("b");
    q.pause();
    expect(q.isPaused()).toBe(true);
    q.enqueue("c");
    q.enqueue("d");
    expect(q.size()).toBe(4);
    q.resume();
    expect(q.isPaused()).toBe(false);
    expect(q.size()).toBe(4);
    expect(q.dequeue().payload).toBe("a");
    expect(q.dequeue().payload).toBe("b");
    expect(q.dequeue().payload).toBe("c");
    expect(q.dequeue().payload).toBe("d");
  });

  test("pause resume multiple cycles", () => {
    const q = new AsyncQueue<number>();
    q.pause();
    q.enqueue(1);
    q.resume();
    q.pause();
    q.enqueue(2);
    q.resume();
    expect(q.size()).toBe(2);
    expect(q.getJobs().map((j) => j.payload)).toEqual([1, 2]);
  });

  test("processJob retry re-enqueues", async () => {
    const q = new AsyncQueue<string>({ retryDelay: 0 });
    const job = q.enqueue("fail", { maxAttempts: 3 });
    // dequeue first
    const dequeued = q.dequeue();
    let attempts = 0;
    const handler = () => {
      attempts++;
      throw new Error("fail");
    };
    const r1 = await q.processJob(dequeued, handler);
    expect(r1.success).toBe(false);
    expect(r1.job.attempts).toBe(1);
    expect(q.size()).toBe(1); // re-enqueued
    const r2 = await q.processJob(q.dequeue(), handler);
    expect(r2.job.attempts).toBe(2);
    expect(q.size()).toBe(1);
    const r3 = await q.processJob(q.dequeue(), handler);
    expect(r3.job.attempts).toBe(3);
    expect(q.size()).toBe(0); // max attempts reached, not re-enqueued
    expect(r3.success).toBe(false);
  });

  test("processJob succeeds", async () => {
    const q = new AsyncQueue<string>();
    const job = q.enqueue("ok");
    const dequeued = q.dequeue();
    const r = await q.processJob(dequeued, async () => {});
    expect(r.success).toBe(true);
    expect(r.job.attempts).toBe(1);
    expect(q.size()).toBe(0);
  });

  test("processNext handles empty", async () => {
    const q = new AsyncQueue<string>();
    expect(await q.processNext(async () => {})).toBeNull();
  });

  test("processNext surfaces errors via retry", async () => {
    const q = new AsyncQueue<string>();
    q.enqueue("x", { maxAttempts: 2 });
    let called = 0;
    const handler = () => {
      called++;
      throw new Error("oops");
    };
    const r1 = await q.processNext(handler);
    expect(r1!.success).toBe(false);
    expect(called).toBe(1);
    const r2 = await q.processNext(handler);
    expect(r2!.success).toBe(false);
    expect(called).toBe(2);
    expect(q.isEmpty()).toBe(true);
    // next should be null
    expect(await q.processNext(handler)).toBeNull();
  });

  test("clear empties queue", () => {
    const q = new AsyncQueue<string>();
    q.enqueue("a");
    q.pause();
    q.enqueue("b");
    q.clear();
    expect(q.isEmpty()).toBe(true);
    expect(q.size()).toBe(0);
  });
});

#!/usr/bin/env node
// V1 helper for file-based hypothesis/evidence tracking inside workspace.
// Usage:
//   node .v1/helpers.js add-hypothesis '{"description":"...","evidence":["file:line"],"confidence":0.8,"files":["src/foo.ts"]}'
//   node .v1/helpers.js select-hypothesis <id>
//   node .v1/helpers.js add-evidence '{"type":"file_inspection","description":"...","source":"src/foo.ts","result":"supports"}'
//   node .v1/helpers.js add-file-inspected src/foo.ts
//   node .v1/helpers.js add-command '{"command":"npm test","exitCode":0,"stdout":"..."}'
//   node .v1/helpers.js add-verification '{"method":"vitest","command":"vitest run","passed":true,"output":"..."}'
//   node .v1/helpers.js status
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { randomUUID } from "node:crypto";

const STATE_PATH = join(process.cwd(), ".v1/state.json");

function load() {
  if (!existsSync(STATE_PATH)) {
    console.error("No .v1/state.json found at", STATE_PATH);
    process.exit(1);
  }
  const raw = readFileSync(STATE_PATH, "utf-8");
  return JSON.parse(raw);
}
function save(s) {
  mkdirSync(dirname(STATE_PATH), { recursive: true });
  writeFileSync(STATE_PATH, JSON.stringify(s, null, 2), "utf-8");
}

const cmd = process.argv[2];
if (!cmd || cmd === "help" || cmd === "--help") {
  console.log("Usage: node .v1/helpers.js <add-hypothesis|select-hypothesis|add-evidence|add-file-inspected|add-command|add-verification|status>");
  process.exit(0);
}
if (cmd === "status") {
  const s = load();
  console.log(JSON.stringify(s, null, 2));
  process.exit(0);
}
if (cmd === "add-hypothesis") {
  const arg = process.argv[3];
  if (!arg) { console.error("need JSON arg"); process.exit(1); }
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { description: arg, evidence: [] }; }
  const s = load();
  const h = {
    id: payload.id ?? `hyp-${randomUUID().slice(0, 8)}`,
    description: payload.description ?? "hypothesis",
    evidence: payload.evidence ?? [],
    confidence: payload.confidence ?? 0.5,
    status: payload.status ?? "active",
    files: payload.files,
  };
  s.hypotheses = s.hypotheses ?? [];
  s.hypotheses.push(h);
  // also push evidence entry for diagnosis
  s.evidence = s.evidence ?? [];
  s.evidence.push({ id: `ev-${randomUUID().slice(0, 8)}`, type: "other", description: `Hypothesis: ${h.description}`, source: h.files?.[0], result: "neutral", timestamp: new Date().toISOString(), phase: s.phase });
  save(s);
  console.log(h.id);
  process.exit(0);
}
if (cmd === "select-hypothesis") {
  const id = process.argv[3];
  if (!id) { console.error("need id"); process.exit(1); }
  const s = load();
  let found = false;
  for (const hyp of s.hypotheses) {
    if (hyp.id === id) { hyp.status = "selected"; s.selectedHypothesis = id; found = true; }
    else if (hyp.status === "selected") hyp.status = "active";
  }
  if (!found) { console.error("hypothesis not found", id); process.exit(1); }
  save(s);
  console.log("selected", id);
  process.exit(0);
}
if (cmd === "add-evidence") {
  const arg = process.argv[3];
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { description: arg }; }
  const s = load();
  s.evidence = s.evidence ?? [];
  s.evidence.push({ id: `ev-${randomUUID().slice(0, 8)}`, type: payload.type ?? "other", description: payload.description ?? arg, source: payload.source, result: payload.result ?? "neutral", timestamp: new Date().toISOString(), phase: payload.phase ?? s.phase });
  save(s);
  console.log("evidence added");
  process.exit(0);
}
if (cmd === "add-file-inspected") {
  const p = process.argv[3];
  const s = load();
  s.filesInspected = s.filesInspected ?? [];
  if (!s.filesInspected.includes(p)) s.filesInspected.push(p);
  save(s);
  console.log("file recorded", p);
  process.exit(0);
}
if (cmd === "add-command") {
  // raw json {command, exitCode, stdout, stderr, durationMs}
  const arg = process.argv.slice(3).join(" ");
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { command: arg }; }
  const s = load();
  s.commandsExecuted = s.commandsExecuted ?? [];
  s.commandsExecuted.push({ command: payload.command ?? arg, exitCode: payload.exitCode ?? null, stdout: payload.stdout ?? "", stderr: payload.stderr ?? "", durationMs: payload.durationMs ?? 0, phase: s.phase, timestamp: new Date().toISOString() });
  save(s);
  console.log("command recorded");
  process.exit(0);
}
if (cmd === "add-verification") {
  const arg = process.argv.slice(3).join(" ");
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { method: arg, output: arg }; }
  const s = load();
  s.verificationAttempts = s.verificationAttempts ?? [];
  s.verificationAttempts.push({ id: `ver-${randomUUID().slice(0, 8)}`, iteration: s.iteration, method: payload.method ?? "manual", command: payload.command, passed: payload.passed ?? null, output: payload.output ?? JSON.stringify(payload), timestamp: new Date().toISOString(), phase: s.phase });
  if (payload.passed !== undefined || payload.output) {
    s.evidence = s.evidence ?? [];
    s.evidence.push({ id: `ev-${randomUUID().slice(0, 8)}`, type: payload.type ?? "test_result", description: `Verification: ${payload.method ?? payload.command ?? "check"}`, source: payload.command, result: payload.passed ? "supports" : payload.passed === false ? "contradicts" : "neutral", timestamp: new Date().toISOString(), phase: s.phase });
  }
  save(s);
  console.log("verification recorded");
  process.exit(0);
}
console.error("unknown command", cmd);
process.exit(1);

